import React, { useState, useEffect } from "react";
import { Modal, View, Text, TextInput, TouchableOpacity, StyleSheet, ScrollView, Alert } from "react-native";

export default function NotaEditor({ onSalvarNota, onAtualizarNota, onExcluirNota, notaEditando, onCancelarEdicao }) {
  const [texto, setTexto] = useState("");
  const [categoria, setCategoria] = useState("Pessoal");
  const [modalVisivel, setModalVisivel] = useState(false);

  const categorias = [
    { label: "Pessoal", value: "Pessoal", cor: "#FF924F" },
    { label: "Trabalho", value: "Trabalho", cor: "#2F71EB" },
    { label: "Estudos", value: "Estudos", cor: "#9C27B0" },
    { label: "Lembretes", value: "Lembretes", cor: "#009688" },
    { label: "Outros", value: "Outros", cor: "#00911F" }
  ];

  useEffect(() => {
    if (notaEditando) {
      setTexto(notaEditando.texto);
      setCategoria(notaEditando.categoria || "Pessoal");
      setModalVisivel(true);
    }
  }, [notaEditando]);

  const handleSalvar = async () => {
    if (!texto.trim()) {
      alert("Por favor, digite algum texto para a nota.");
      return;
    }

    try {
      let sucesso = false;

      if (notaEditando) {
        sucesso = await onAtualizarNota(notaEditando.id, texto, categoria);
        if (sucesso) {
          console.log("✅ Nota atualizada com sucesso");
        }
      } else {
        sucesso = await onSalvarNota(texto, categoria);
        if (sucesso) {
          console.log("✅ Nova nota criada com sucesso");
        }
      }

      if (sucesso) {
        limparEfechar();
      } else {
        alert("Erro ao salvar a nota.");
      }
    } catch (error) {
      console.error("Erro:", error);
      alert("Erro ao salvar a nota.");
    }
  };

  const handleExcluir = () => {
    if (!notaEditando) return;

    Alert.alert(
      "Excluir Nota",
      "Tem certeza que deseja excluir esta nota?",
      [
        { text: "Cancelar", style: "cancel" },
        { 
          text: "Excluir", 
          style: "destructive",
          onPress: async () => {
            try {
              console.log("🗑️ Excluindo nota:", notaEditando.id);
              await onExcluirNota(notaEditando.id);
              console.log("✅ Nota excluída com sucesso");
              limparEfechar();
            } catch (error) {
              console.error("❌ Erro ao excluir:", error);
              alert("Erro ao excluir a nota.");
            }
          }
        }
      ]
    );
  };

  const limparEfechar = () => {
    setTexto("");
    setCategoria("Pessoal");
    setModalVisivel(false);
    onCancelarEdicao?.();
  };

  const corCategoriaSelecionada = categorias.find(cat => cat.value === categoria)?.cor || "#FF924F";

  return (
    <>
      <Modal
        animationType="slide"
        transparent={true}
        visible={modalVisivel}
        onRequestClose={limparEfechar}
      >
        <View style={estilos.centralizaModal}>
          <ScrollView showsVerticalScrollIndicator={false}>
            <View style={estilos.modal}>
              <Text style={estilos.modalTitulo}>
                {notaEditando ? "Editar nota" : "Criar nota"}
              </Text>

              <Text style={estilos.modalSubTitulo}>Categoria</Text>
              <View style={[estilos.categoriaContainer, { borderColor: corCategoriaSelecionada }]}>
                <View style={estilos.categoriasLista}>
                  {categorias.map((cat) => (
                    <TouchableOpacity
                      key={cat.value}
                      style={[
                        estilos.categoriaBotao,
                        categoria === cat.value && { backgroundColor: cat.cor }
                      ]}
                      onPress={() => setCategoria(cat.value)}
                    >
                      <Text style={[
                        estilos.categoriaBotaoTexto,
                        categoria === cat.value && estilos.categoriaBotaoTextoSelecionado
                      ]}>
                        {cat.label}
                      </Text>
                    </TouchableOpacity>
                  ))}
                </View>
              </View>

              <Text style={estilos.modalSubTitulo}>Conteúdo da nota</Text>
              <TextInput
                style={estilos.modalInput}
                multiline={true}
                numberOfLines={4}
                onChangeText={setTexto}
                placeholder="Digite aqui seu lembrete..."
                value={texto}
                autoFocus={true}
              />

              <View style={estilos.modalBotoes}>
                {notaEditando && (
                  <TouchableOpacity
                    style={estilos.modalBotaoExcluir}
                    onPress={handleExcluir}
                  >
                    <Text style={estilos.modalBotaoTexto}>Excluir</Text>
                  </TouchableOpacity>
                )}

                <TouchableOpacity
                  style={estilos.modalBotaoCancelar}
                  onPress={limparEfechar}
                >
                  <Text style={estilos.modalBotaoTexto}>Cancelar</Text>
                </TouchableOpacity>

                <TouchableOpacity
                  style={estilos.modalBotaoSalvar}
                  onPress={handleSalvar}
                >
                  <Text style={estilos.modalBotaoTexto}>
                    {notaEditando ? "Atualizar" : "Salvar"}
                  </Text>
                </TouchableOpacity>
              </View>
            </View>
          </ScrollView>
        </View>
      </Modal>

      {!notaEditando && (
        <TouchableOpacity
          onPress={() => setModalVisivel(true)}
          style={estilos.adicionarMemo}
        >
          <Text style={estilos.adicionarMemoTexto}>+</Text>
        </TouchableOpacity>
      )}
    </>
  );
}

const estilos = StyleSheet.create({
  centralizaModal: {
    flex: 1,
    flexDirection: "row",
    alignItems: "flex-end",
  },
  modal: {
    backgroundColor: "#FFFFFF",
    paddingHorizontal: 16,
    paddingTop: 16,
    paddingBottom: 32,
    marginTop: 8,
    marginHorizontal: 16,
    borderTopLeftRadius: 8,
    borderTopRightRadius: 8,
    shadowColor: "#000",
    shadowOffset: {
      width: 0,
      height: 5,
    },
    shadowOpacity: 0.34,
    shadowRadius: 6.27,
    elevation: 10,
  },
  modalTitulo: {
    fontSize: 28,
    fontWeight: "600",
    marginBottom: 18,
  },
  modalInput: {
    fontSize: 18,
    marginBottom: 12,
    paddingHorizontal: 8,
    paddingVertical: 8,
    borderBottomWidth: 1,
    borderBottomColor: "#FF9A94",
    minHeight: 100,
    textAlignVertical: "top",
  },
  modalSubTitulo: {
    fontSize: 14,
    marginBottom: 8,
    fontWeight: "600",
    color: "#333",
  },
  categoriaContainer: {
    borderWidth: 2,
    borderRadius: 8,
    marginBottom: 16,
    padding: 8,
    backgroundColor: "#f8f8f8",
  },
  categoriasLista: {
    flexDirection: "row",
    flexWrap: "wrap",
    gap: 8,
  },
  categoriaBotao: {
    paddingHorizontal: 12,
    paddingVertical: 6,
    borderRadius: 15,
    borderWidth: 1,
    borderColor: "#ddd",
    backgroundColor: "#f0f0f0",
  },
  categoriaBotaoTexto: {
    fontSize: 12,
    fontWeight: "500",
    color: "#666",
  },
  categoriaBotaoTextoSelecionado: {
    color: "#FFFFFF",
    fontWeight: "bold",
  },
  modalBotoes: {
    flexDirection: "row",
    justifyContent: "space-between",
    marginTop: 16,
  },
  modalBotaoSalvar: {
    backgroundColor: "#2ea805",
    borderRadius: 5,
    padding: 12,
    width: 100,
    alignItems: "center",
  },
  modalBotaoCancelar: {
    backgroundColor: "#057fa8",
    borderRadius: 5,
    padding: 12,
    width: 100,
    alignItems: "center",
  },
  modalBotaoExcluir: {
    backgroundColor: "#d62a18",
    borderRadius: 5,
    padding: 12,
    width: 100,
    alignItems: "center",
  },
  modalBotaoTexto: {
    color: "#FFFFFF",
    fontWeight: "bold",
  },
  adicionarMemo: {
    backgroundColor: "#54ba32",
    justifyContent: "center",
    height: 64,
    width: 64,
    margin: 16,
    alignItems: "center",
    borderRadius: 32,
    position: "absolute",
    bottom: 0,
    right: 0,
    shadowColor: "#000",
    shadowOffset: {
      width: 0,
      height: 2,
    },
    shadowOpacity: 0.23,
    shadowRadius: 2.62,
    elevation: 4,
  },
  adicionarMemoTexto: {
    fontSize: 32,
    lineHeight: 40,
    color: "#FFFFFF",
  },
});
